@startuml

class Well {
  + code : string
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class PollutionRate {}

class OnshoreWell {
  + surfaceExtension : double
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalAreaCode : string
  + environmentalImportance : int
}

class ExtractsCrudeOil {
  + quantity : double
}

class BelongsTo {
  + category : string
}

Well "1" -- "*" Company : extractsCrudeOil
Company "0..*" -- "1" Well : belongsTo
Well "1" -- "1" PollutionRate : hasPollutionRate
OnshoreWell "1" -- "1" Well : is
OffshoreWell "1" -- "1" Well : is
PollutionRate "1" -- "1" OnshoreWell : for
PollutionRate "1" -- "1" OffshoreWell : for
ExtractsCrudeOil "0..*" -- "1" Company : by

@enduml

